edits.oldText:
export function composeChildPrompt(input: {
	family: PromptFamily;
	rolePrompt: string;
	includesFamilyShared?: boolean;
	root?: string;
}): { family: PromptFamily; text: string; files: string[] } {
	const rolePrompt = input.rolePrompt.trim();
	if (input.includesFamilyShared || input.family === "pi-default") {
		return {
			family: input.family,
			text: rolePrompt,
			files: rolePrompt ? ["role"] : [],
		};
	}
	const shared = familySharedBody(input.family, input.root).trim();
	if (!shared) {
		return {
			family: input.family,
			text: rolePrompt,
			files: rolePrompt ? ["role"] : [],
		};
	}
	if (rolePrompt.includes(shared)) {
		return {
			family: input.family,
			text: rolePrompt,
			files: [`${input.family}/shared.md`, "role"],
		};
	}
	const text = [shared, rolePrompt].filter(Boolean).join("\n");
	return {
		family: input.family,
		text,
		files: rolePrompt ? [`${input.family}/shared.md`, "role"] : [`${input.family}/shared.md`],
	};
}

edits.newText:
export function composeChildPrompt(input: {
	family: PromptFamily;
	rolePrompt: string;
	includesFamilyShared?: boolean;
	common?: boolean;
	root?: string;
}): { family: PromptFamily; text: string; files: string[] } {
	const rolePrompt = input.rolePrompt.trim();
	if (input.family === "pi-default") {
		return {
			family: input.family,
			text: rolePrompt,
			files: rolePrompt ? ["role"] : [],
		};
	}
	let text: string;
	let files: string[];
	if (input.includesFamilyShared) {
		text = rolePrompt;
		files = rolePrompt ? ["role"] : [];
	} else {
		const shared = familySharedBody(input.family, input.root).trim();
		if (!shared) {
			text = rolePrompt;
			files = rolePrompt ? ["role"] : [];
		} else if (rolePrompt.includes(shared)) {
			text = rolePrompt;
			files = [`${input.family}/shared.md`, "role"];
		} else {
			text = [shared, rolePrompt].filter(Boolean).join("\n");
			files = rolePrompt ? [`${input.family}/shared.md`, "role"] : [`${input.family}/shared.md`];
		}
	}
	if (input.common) {
		const commonText = commonBody(input.root).trim();
		if (commonText && !text.includes(commonText)) {
			text = text ? `${text}\n${commonText}` : commonText;
			files = [...files, "common.md"];
		} else if (commonText && text.includes(commonText) && !files.includes("common.md")) {
			// Already baked in (e.g. a previously composed prompt): keep text
			// unchanged and report the common layer for consistency only if
			// the shared layer is present in the file list.
			if (files.includes(`${input.family}/shared.md`)) files = [...files, "common.md"];
		}
	}
	return { family: input.family, text, files };
}

