import { commonBody, defaultSourcesRoot, loadHarnessSources, overlayBody, renderOverlay } from "./prompt.ts";

test("every parent harness name has a SOURCE profile and listed overlay files exist", () => {
	const loaded = loadHarnessSources();
	assert.ok(loaded.length > 0);
	const claimed = new Set<string>();
	for (const source of loaded) {
		assert.equal(source.family, source.dir.split("/").at(-1));
		assert.match(source.ref.rev, /^[0-9a-f]{40}$/);
		if (source.shared) {
			assert.equal(existsSync(join(source.dir, source.shared)), true, source.shared);
		}
		for (const [name, profile] of Object.entries(source.profiles)) {
			assert.equal(claimed.has(name), false, `duplicate profile ${name}`);
			claimed.add(name);
			if (profile.overlay) {
				assert.equal(existsSync(join(source.dir, profile.overlay)), true, profile.overlay);
			}
		}
	}
	assert.deepEqual([...claimed].sort(), [...HARNESS_NAMES].sort());
});

