export function familySharedBody(family: string, root?: string): string {
	for (const source of sources(root)) {
		if (source.family !== family) continue;
		return readOptional(source.dir, source.shared);
	}
	return "";
}

export function commonBody(root?: string): string {
	const candidates = root ? [join(root, "common.md"), join(defaultSourcesRoot(), "common.md")] : [join(defaultSourcesRoot(), "common.md")];
	for (const path of candidates) {
		if (existsSync(path)) return readFileSync(path, "utf8").trim();
	}
	return "Think concisely. Keep internal reasoning brief and focused on the immediate step. Output tool calls directly without conversational filler.";
}

export function overlayBody(name: HarnessName, root?: string, common = true): string {
	for (const source of sources(root)) {
		const profile = source.profiles[name];
		if (!profile) continue;
		const parts = [readOptional(source.dir, source.shared), readOptional(source.dir, profile.overlay)];
		let body = parts.filter(Boolean).join("\n");
		if (common && !String(name).endsWith("-plan")) {
			const commonText = commonBody(root);
			if (commonText && !body.includes(commonText)) {
				body = body ? `${body}\n${commonText}` : commonText;
			}
		}
		return body;
	}
	throw new Error(`No overlay source for harness ${name}`);
}

